code_example:
#include <iostream>
#include <array>
template <typename T, size_t N>
struct StaticArray {
  T data[N];
  size_t size() const { return N; }
};

template <typename T, size_t N>
void printArray(const StaticArray<T, N>& arr) {
  for (size_t i = 0; i < arr.size(); ++i) {
    std::cout << arr.data[i] << " ";
  }
  std::cout << std::endl;
}

int main() {
  StaticArray<int, 5> arr = {{1, 2, 3, 4, 5}};
  printArray(arr);
  StaticArray<double, 3> arr2 = {{1.1, 2.2, 3.3}};
  printArray(arr2); 
  return 0;
}
// Compile-time array size and type are determined.
// The compiler generates specialized code for each instantiation of StaticArray.
